for name in ['public/index.html','public/admin.html']:
    path=ROOT/name
    if not path.is_file(): raise SystemExit('Đặt script cạnh firebase.json trong dự án.')
    text=path.read_text(encoding='utf-8-sig')
    if 'season-themes.css' not in text: raise SystemExit('Chạy fix_cheng_themes.py trước khi nâng cấp giao diện.')
    FILES[name]=re.sub(r'season-themes\.css(?:\?v=[^"\s<>]+)?','season-themes.css?v=luxury1',text)
backup=ROOT/'cheng-backups'/datetime.now().strftime('design-%Y%m%d-%H%M%S-%f')
for name in FILES:
    path=ROOT/name
    if path.is_file():
        saved=backup/name
        saved.parent.mkdir(parents=True,exist_ok=True)
        shutil.copy2(path,saved)
for name,content in FILES.items():
    path=ROOT/name
    path.parent.mkdir(parents=True,exist_ok=True)
    path.write_text(content,encoding='utf-8')
print('Đã cập nhật thiết kế 4 mùa. Sao lưu: '+str(backup))